run.configTemplate:
RNACOS_HTTP_PORT={port}
RNACOS_GRPC_PORT={port+1000}
RNACOS_HTTP_CONSOLE_PORT={port+2000}
RNACOS_DATA_DIR={data}/nacos_db
RNACOS_CONFIG_DB_FILE={data}/nacos_db/config.db
RNACOS_NAMING_DB_FILE={data}/nacos_db/naming.db

test {
    template IN ANY test {
        answer "{{ .Name }} 60 IN A 127.0.0.1"
    }
    errors
}
. {
    forward . 8.8.8.8 1.1.1.1
    errors
}

[mysqld]
basedir={root}/..
datadir={data}
port={port}
character-set-server=utf8mb4
collation-server=utf8mb4_unicode_ci

[client]
port={port}
default-character-set=utf8mb4

{
	storage file_system {data}/storage
	admin off
}
